import numpy as np, json, importlib.util
spec=importlib.util.spec_from_file_location('rs','method/response_surface.py'); rs=importlib.util.module_from_spec(spec); spec.loader.exec_module(rs)
d=json.load(open('lab/input-final.json')); rows=d['observations']
pts=np.array([[r['x'],r['y']] for r in rows]); vals=np.array([r['value'] for r in rows]); imp=np.array([r['impurity'] for r in rows]); scaled=2*pts-1
for name,v,noise in [('yield',vals,0.18),('impurity',imp,0.01)]:
    for inter in [False,True]:
        m=rs.fit(scaled,v,inter,noise); A=rs.design(scaled,inter); res=v-A@m['coefficients']
        lev=np.sum((A@m['inverse'])*A,axis=1); loo=res/(1-lev)
        print(f'--- {name} inter={inter} cv={m["cv_rmse"]:.5f} rss/df={res@res/(len(v)-A.shape[1]):.6f} varfloor={noise**2:.6f}')
        for r,e,l in zip(rows,res,loo):
            print(f'   {r["x"]:.2f},{r["y"]:.2f} obs={r["value"] if name=="yield" else r["impurity"]:.6f} res={e:+.5f} loo={l:+.5f} lev={lev[list(rows).index(r)]:.3f}')
EOF","description":"Compute residuals and LOO residuals"}

